CREATE TABLE rooms (code TEXT PRIMARY KEY, public INTEGER NOT NULL DEFAULT 0, host TEXT NOT NULL, seed INTEGER NOT NULL, starts_at INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE players (id TEXT NOT NULL, room TEXT NOT NULL REFERENCES rooms(code) ON DELETE CASCADE, token TEXT NOT NULL, name TEXT NOT NULL, color INTEGER NOT NULL, position INTEGER NOT NULL DEFAULT 0, correct INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, seen_at INTEGER NOT NULL, PRIMARY KEY (room, id));
CREATE INDEX players_room ON players(room);
